CREATE TYPE "GovernanceApprovalStatus" AS ENUM ('NOT_REQUIRED','PENDING','APPROVED','REJECTED');
CREATE TABLE "ai_provider_records" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"provider_key" TEXT NOT NULL,"model_key" TEXT NOT NULL,"display_name" TEXT NOT NULL,"is_active" BOOLEAN NOT NULL DEFAULT true,"metadata" JSONB,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "ai_provider_records_pkey" PRIMARY KEY("id"));
CREATE TABLE "prompt_template_versions" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"template_key" TEXT NOT NULL,"version" INTEGER NOT NULL,"purpose" TEXT NOT NULL,"template_sha" TEXT NOT NULL,"template" TEXT NOT NULL,"is_active" BOOLEAN NOT NULL DEFAULT true,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "prompt_template_versions_pkey" PRIMARY KEY("id"));
CREATE TABLE "ai_usage_logs" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"tenant_id" UUID,"campaign_id" UUID,"actor_id" UUID,"provider_record_id" UUID,"prompt_template_version_id" UUID,"feature" TEXT NOT NULL,"request_id" TEXT,"generated_output_reference" TEXT,"reviewer_id" UUID,"approval_status" "GovernanceApprovalStatus" NOT NULL DEFAULT 'NOT_REQUIRED',"safety_flags" JSONB NOT NULL,"source_grounding_metadata" JSONB NOT NULL,"provider_response_id" TEXT,"input_sha256" TEXT NOT NULL,"status" TEXT NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ai_usage_logs_pkey" PRIMARY KEY("id"));
CREATE TABLE "ai_error_reports" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"tenant_id" UUID,"ai_usage_log_id" UUID,"request_id" TEXT,"error_code" TEXT NOT NULL,"safe_message" TEXT NOT NULL,"metadata" JSONB,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ai_error_reports_pkey" PRIMARY KEY("id"));
CREATE UNIQUE INDEX "ai_provider_records_provider_key_model_key_key" ON "ai_provider_records"("provider_key","model_key"); CREATE UNIQUE INDEX "prompt_template_versions_template_key_version_key" ON "prompt_template_versions"("template_key","version"); CREATE INDEX "prompt_template_versions_template_key_is_active_idx" ON "prompt_template_versions"("template_key","is_active"); CREATE INDEX "ai_usage_logs_tenant_id_created_at_idx" ON "ai_usage_logs"("tenant_id","created_at"); CREATE INDEX "ai_usage_logs_campaign_id_feature_created_at_idx" ON "ai_usage_logs"("campaign_id","feature","created_at"); CREATE INDEX "ai_error_reports_tenant_id_created_at_idx" ON "ai_error_reports"("tenant_id","created_at");
ALTER TABLE "ai_usage_logs" ADD CONSTRAINT "ai_usage_logs_provider_record_id_fkey" FOREIGN KEY("provider_record_id") REFERENCES "ai_provider_records"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "ai_usage_logs" ADD CONSTRAINT "ai_usage_logs_prompt_template_version_id_fkey" FOREIGN KEY("prompt_template_version_id") REFERENCES "prompt_template_versions"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "ai_error_reports" ADD CONSTRAINT "ai_error_reports_ai_usage_log_id_fkey" FOREIGN KEY("ai_usage_log_id") REFERENCES "ai_usage_logs"("id") ON DELETE SET NULL ON UPDATE CASCADE;
CREATE OR REPLACE FUNCTION prevent_governance_log_mutation() RETURNS trigger AS $$ BEGIN RAISE EXCEPTION 'governance logs are append-only'; END; $$ LANGUAGE plpgsql;
CREATE TRIGGER security_audit_events_append_only BEFORE UPDATE OR DELETE ON "security_audit_events" FOR EACH ROW EXECUTE FUNCTION prevent_governance_log_mutation();
CREATE TRIGGER ai_usage_logs_append_only BEFORE UPDATE OR DELETE ON "ai_usage_logs" FOR EACH ROW EXECUTE FUNCTION prevent_governance_log_mutation();
CREATE TRIGGER ai_error_reports_append_only BEFORE UPDATE OR DELETE ON "ai_error_reports" FOR EACH ROW EXECUTE FUNCTION prevent_governance_log_mutation();
